-- Step 2: the Catalog (Card 5). Ids are uuid v7, generated by the Go code; name_search is written by the service.

-- +goose Up
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Order matters: sorting by size follows the enum order.
CREATE TYPE creature_size AS ENUM ('tiny', 'small', 'medium', 'large', 'huge', 'gargantuan');

CREATE TYPE creature_type AS ENUM (
    'aberration', 'beast', 'celestial', 'construct', 'dragon', 'elemental', 'fey',
    'fiend', 'giant', 'humanoid', 'monstrosity', 'ooze', 'plant', 'undead'
);

CREATE TYPE paint_status AS ENUM ('pre_painted', 'hand_painted', 'unpainted');

CREATE TABLE miniatures (
    id               uuid PRIMARY KEY,
    -- Users are deactivated, never deleted, so these never cascade (Card 4 rule 7).
    owner_id         uuid          NOT NULL REFERENCES users (id),
    created_by       uuid          NOT NULL REFERENCES users (id),
    name             varchar(100)  NOT NULL CHECK (char_length(name) >= 1),
    name_search      text          NOT NULL,
    creature_type    creature_type NOT NULL,
    size             creature_size NOT NULL,
    -- The official 5e values: 0, 1/8, 1/4, 1/2, then whole numbers 1 to 30 (Card 5 rule 2).
    challenge_rating numeric(5, 3) CHECK (
        challenge_rating IN (0, 0.125, 0.25, 0.5)
        OR (challenge_rating BETWEEN 1 AND 30 AND challenge_rating = trunc(challenge_rating))
    ),
    quantity         smallint      NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 999),
    paint_status     paint_status  NOT NULL DEFAULT 'unpainted',
    -- Tag format is checked by the service (Card 5 rule 3); the database only caps the count.
    tags             text[]        NOT NULL DEFAULT '{}' CHECK (cardinality(tags) <= 20),
    storage_location varchar(60),
    manufacturer     varchar(60),
    notes            varchar(1000),
    -- Empty in the MVP (docs/plan.md, section 4).
    system_stats     jsonb         NOT NULL DEFAULT '{}',
    custom_fields    jsonb         NOT NULL DEFAULT '{}',
    -- Optimistic locking: an update must carry the current version (Card 5 rule 7).
    version          integer       NOT NULL DEFAULT 1,
    created_at       timestamptz   NOT NULL DEFAULT now(),
    updated_at       timestamptz   NOT NULL DEFAULT now()
);

-- The filter indexes from docs/plan.md ("Indexes for the filters"); step 3's filters use them.
CREATE INDEX miniatures_owner_id_idx ON miniatures (owner_id);
CREATE INDEX miniatures_creature_type_idx ON miniatures (creature_type);
CREATE INDEX miniatures_size_idx ON miniatures (size);
CREATE INDEX miniatures_paint_status_idx ON miniatures (paint_status);
CREATE INDEX miniatures_challenge_rating_idx ON miniatures (challenge_rating);
CREATE INDEX miniatures_tags_idx ON miniatures USING gin (tags);
CREATE INDEX miniatures_name_search_trgm_idx ON miniatures USING gin (name_search gin_trgm_ops);
CREATE INDEX miniatures_name_search_id_idx ON miniatures (name_search, id);
CREATE INDEX miniatures_created_at_idx ON miniatures (created_at);

-- +goose Down
DROP TABLE miniatures;
DROP TYPE paint_status;
DROP TYPE creature_type;
DROP TYPE creature_size;
